class Calculator:

    def __init__(self):
        self.operators = {'+': lambda x, y: x + y, '-': lambda x, y: x - y, '*': lambda x, y: x * y, '/': lambda x, y: x / y, '^': lambda x, y: x ** y}

    def calculate(self, expression):
        import re
        tokens = re.findall('\\d+|\\+|\\-|\\*|\\/|\\^|\\(|\\)', expression)
        operand_stack = []
        operator_stack = []
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
        for token in tokens:
            if token.isdigit():
                operand_stack.append(float(token))
            elif token == '(':
                operator_stack.append(token)
            elif token == ')':
                while operator_stack and operator_stack[-1] != '(':
                    operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)
                operator_stack.pop()
            else:
                while operator_stack and operator_stack[-1] != '(' and (precedence[operator_stack[-1]] >= precedence[token]):
                    operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)
                operator_stack.append(token)
        while operator_stack:
            operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)
        return operand_stack[0] if operand_stack else None

    def precedence(self, operator):
        """Returns the priority of the specified operator, where the higher the priority, the greater the assignment. The priority of '^' is greater than '/' and '*', and the priority of '/' and '*' is greater than '+' and '-'
        :param operator: string, given operator
        :return: int, the priority of the given operator, otherwise return 0
        """
        if operator == '^':
            return 3
        elif operator in ('/', '*'):
            return 2
        elif operator in ('+', '-'):
            return 1
        else:
            return 0

    def apply_operator(self, operand_stack, operator_stack):
        operator = operator_stack.pop()
        right = operand_stack.pop()
        left = operand_stack.pop()
        result = self.operators[operator](left, right)
        operand_stack.append(result)
        return (operand_stack, operator_stack)

